CREATE TABLE tenants (
 id uuid PRIMARY KEY, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE tenant_rate_limits (
 id uuid PRIMARY KEY, tenant_id uuid NOT NULL UNIQUE REFERENCES tenants(id), requests_per_minute integer NOT NULL DEFAULT 100 CHECK(requests_per_minute>0), events_per_minute integer NOT NULL DEFAULT 10000 CHECK(events_per_minute>0), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE app_users (
 id uuid PRIMARY KEY, tenant_id uuid REFERENCES tenants(id), user_name varchar(256) NOT NULL, normalized_user_name varchar(256) NOT NULL UNIQUE, email varchar(256), normalized_email varchar(256), email_confirmed boolean NOT NULL DEFAULT false, password_hash text NOT NULL, security_stamp text, concurrency_stamp text, phone_number text, phone_number_confirmed boolean NOT NULL DEFAULT false, two_factor_enabled boolean NOT NULL DEFAULT false, lockout_end timestamptz, lockout_enabled boolean NOT NULL DEFAULT true, access_failed_count integer NOT NULL DEFAULT 0, disabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id)
);
CREATE TABLE app_roles (
 id uuid PRIMARY KEY, name varchar(256) NOT NULL UNIQUE, normalized_name varchar(256) NOT NULL UNIQUE, concurrency_stamp text
);
CREATE TABLE app_user_roles (
 id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, role_id uuid NOT NULL REFERENCES app_roles(id), UNIQUE(user_id,role_id)
);
CREATE TABLE app_user_claims (
 id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, claim_type text, claim_value text
);
CREATE TABLE app_role_claims (
 id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, role_id uuid NOT NULL REFERENCES app_roles(id) ON DELETE CASCADE, claim_type text, claim_value text
);
CREATE TABLE app_user_logins (
 login_provider text NOT NULL, provider_key text NOT NULL, provider_display_name text, user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, PRIMARY KEY(login_provider,provider_key)
);
CREATE TABLE app_user_tokens (
 user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, login_provider text NOT NULL, name text NOT NULL, value text, PRIMARY KEY(user_id,login_provider,name)
);
CREATE TABLE user_refresh_tokens (
 id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES app_users(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE devices (
 id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id)
);
CREATE TABLE device_api_keys (
 id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), device_id uuid NOT NULL, digest bytea NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,device_id) REFERENCES devices(tenant_id,id)
);
CREATE TABLE telemetry_events (
 id uuid NOT NULL, tenant_id uuid NOT NULL REFERENCES tenants(id), device_id uuid NOT NULL, event_id uuid NOT NULL, metric text NOT NULL, value double precision NOT NULL, occurred_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(occurred_at,id), FOREIGN KEY(tenant_id,device_id) REFERENCES devices(tenant_id,id)
) PARTITION BY RANGE (occurred_at);
CREATE TABLE telemetry_idempotency (
 id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), device_id uuid NOT NULL, event_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,device_id) REFERENCES devices(tenant_id,id), UNIQUE(tenant_id,device_id,event_id)
);
CREATE TABLE alert_rules (
 id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), device_id uuid NOT NULL, name text NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,device_id) REFERENCES devices(tenant_id,id)
);
CREATE TABLE rule_versions (
 id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), rule_id uuid NOT NULL, version integer NOT NULL CHECK(version>0), kind text NOT NULL CHECK(kind IN ('threshold','rate-of-change')), metric text NOT NULL, threshold double precision NOT NULL, window_seconds integer NOT NULL CHECK(window_seconds BETWEEN 1 AND 259200), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(rule_id,version), FOREIGN KEY(tenant_id,rule_id) REFERENCES alert_rules(tenant_id,id)
);
CREATE TABLE suppression_policies (
 id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), rule_id uuid NOT NULL, seconds integer NOT NULL DEFAULT 300 CHECK(seconds>=0), last_alert_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,rule_id), FOREIGN KEY(tenant_id,rule_id) REFERENCES alert_rules(tenant_id,id)
);
CREATE TABLE alerts (
 id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), device_id uuid NOT NULL, rule_version_id uuid NOT NULL, event_id uuid NOT NULL, state text NOT NULL DEFAULT 'OPEN' CHECK(state IN ('OPEN','ACKNOWLEDGED','RESOLVED')), message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,rule_version_id,event_id), FOREIGN KEY(tenant_id,device_id) REFERENCES devices(tenant_id,id), FOREIGN KEY(tenant_id,rule_version_id) REFERENCES rule_versions(tenant_id,id)
);
CREATE TABLE alert_transitions (
 id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), alert_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES app_users(id), from_state text NOT NULL, to_state text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,alert_id) REFERENCES alerts(tenant_id,id)
);
CREATE TABLE hourly_rollups (
 id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), device_id uuid NOT NULL, metric text NOT NULL, hour timestamptz NOT NULL, count bigint NOT NULL, sum double precision NOT NULL, min double precision NOT NULL, max double precision NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,device_id,metric,hour), FOREIGN KEY(tenant_id,device_id) REFERENCES devices(tenant_id,id)
);
CREATE TABLE outbox_messages (
 id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), kind text NOT NULL, payload jsonb NOT NULL, attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO app_roles(id,name,normalized_name)
SELECT gen_random_uuid(),name,upper(name)
FROM unnest(ARRAY['platform-admin','tenant-admin','operator','viewer']) AS name;
